import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { defineConfig } from "vite";
import { cloudflare } from "@cloudflare/vite-plugin";
import { tanstackStart } from "@tanstack/react-start/plugin/vite";
import viteReact from "@vitejs/plugin-react";

// SOURCE-OF-TRUTH: runs on Cloudflare Workers (Spec 4). Server env comes from
// wrangler `vars` + secrets in production and from this app's `.dev.vars`
// locally — generated by `npm run dev-vars` from the root/app `.env.local`, so
// there is deliberately no loadEnv → process.env loop here any more.
const appDir = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(appDir, "../..");
const pkgSrc = (p: string, entry = "index") => resolve(repoRoot, `packages/${p}/src/${entry}.ts`);

// The Cloudflare plugin resolves the worker env with the `browser` *condition*
// (workerd, worker, module, browser) but leaves `mainFields` at Vite's server
// default, so packages that swap files through the `browser` *field* resolve
// inconsistently. `@aws-sdk/*` is exactly that: `@aws-sdk/core/client` resolves
// to its browser build via the exports condition (where node-only helpers are
// `Symbol.for("node-only")` stubs) while `@aws-sdk/client-s3`'s node
// `runtimeConfig.js` is kept, and the two mix into one bundle — the stub gets
// called as a function while building the S3 client. Browser-first mainFields
// keeps the whole worker graph on the browser (fetch-based) builds, which is
// what the condition list already asks for and what workerd can run.
const workerMainFields = ["browser", "module", "jsnext:main", "jsnext"];

export default defineConfig({
  resolve: {
    tsconfigPaths: true,
    // Every @smartekai package ships a CommonJS `dist/`. Workerd has no
    // `require`, so those files must be bundled — and the only bundler in dev
    // is Vite's dep optimizer, which (rolldown) splits them into chunks whose
    // lazy CommonJS init functions are imported by single-letter name. Through
    // Vite's SSR module runner those lookups come back undefined
    // ("(0, __vite_ssr_import_1__.n) is not a function" on every route), so the
    // app's own packages resolve to their TypeScript source instead. Source is
    // ESM, so there is nothing to interop, and it is what the packages are
    // built from anyway (dist/ is a build artifact). Deep subpaths are listed
    // because each is its own entry in the packages' `exports`.
    alias: [
      { find: /^@smartekai\/ai$/, replacement: pkgSrc("ai") },
      { find: /^@smartekai\/auth\/factory$/, replacement: pkgSrc("auth", "factory") },
      { find: /^@smartekai\/db\/cars$/, replacement: pkgSrc("db", "cars/index") },
      { find: /^@smartekai\/nowpayments$/, replacement: pkgSrc("nowpayments") },
      { find: /^@smartekai\/storage$/, replacement: pkgSrc("storage") },
      { find: /^@smartekai\/ui$/, replacement: pkgSrc("ui") },
    ],
  },
  plugins: [cloudflare({ viteEnvironment: { name: "ssr" } }), tanstackStart(), viteReact()],
  environments: {
    ssr: {
      resolve: { mainFields: workerMainFields },
      // The dep optimizer is its own rolldown pass and does not inherit the
      // env's resolve options, so it needs the same mainFields.
      optimizeDeps: {
        rolldownOptions: { resolve: { mainFields: workerMainFields, aliasFields: [["browser"]] } },
      },
    },
  },
});
